package ru.railbrake.calculator.core

/**
 * Предметные деревья для критичных карточек, которые в расширенном каталоге
 * начинались с универсального шаблона. Здесь уточняется наблюдение и граница
 * допуска, но не добавляются ремонтные операции или обходы защит.
 */
object DiagnosticDeepening {
    fun enrich(scenario: DiagnosticScenario): DiagnosticScenario = when (scenario.id) {
        "aux-common-loss" -> scenario.deepen(
