    private fun DiagnosticScenario.deepen(
        questions: List<DiagnosticQuestion>,
        causes: List<String>,
        checks: List<DiagnosticCheck>,
        related: List<String>
    ) = copy(
        questions = questions,
        probableCauses = causes,
        checks = checks,
        relatedScenarioIds = related,
        trainingNotes = listOf(
            "Сначала сопоставьте команду, прибор и фактическое действие системы.",
            "Отделяйте общий отказ источника от локальной ветви или механизма.",
            "Не воспроизводите опасный режим ради подтверждения гипотезы."
        ),
        feedbackPrompts = listOf(
            "Какие давления и приборы изменились первыми?",
            "Отличается ли одна секция, тележка или группа?",
            "Что произошло после снятия нагрузки или команды отпуска?"
        )
    )

    private fun q(key: String, text: String, yes: String, no: String, next: String) = DiagnosticQuestion(
        key = key,
        text = text,
        yesMeaning = yes,
        noMeaning = no,
        unknownMeaning = "Считать состояние неподтверждённым, записать наблюдение и не расширять действия.",
        yesNextKey = next,
        noNextKey = next,
        unknownNextKey = next
    )

    private fun cab(title: String, action: String, expected: String, abnormal: String) =
        DiagnosticCheck(title, action, expected, abnormal, DiagnosticActionLevel.CAB)

    private fun stop(title: String, action: String, expected: String, abnormal: String) =
        DiagnosticCheck(title, action, expected, abnormal, DiagnosticActionLevel.SAFE_STOP)

    private fun authorized(title: String, action: String, expected: String, abnormal: String) =
        DiagnosticCheck(title, action, expected, abnormal, DiagnosticActionLevel.AUTHORIZED_ONLY)
}
